    size_t len;
};

static struct entry *entries;
static DEFINE_MUTEX(entry_lock);

static int add_entry(const char __user *user_buf, size_t user_len)
{
    struct entry *new_entry;
    size_t total_size;
    int idx;

    if (user_len > MAX_BUF_SIZE)
        return -EINVAL;

    mutex_lock(&entry_lock);

    /* 查找空闲槽位 */
    for (idx = 0; idx < MAX_ENTRIES; idx++) {
        if (entries[idx].data == NULL)
            break;
    }
    if (idx == MAX_ENTRIES) {
        mutex_unlock(&entry_lock);
        return -ENOSPC;
    }

    /* 分配内存：header + data */
    total_size = sizeof(struct entry) + user_len;  // line 28: 整数溢出点
    new_entry = kmalloc(total_size, GFP_KERNEL);
    if (!new_entry) {
        mutex_unlock(&entry_lock);
        return -ENOMEM;
    }

    new_entry->len = user_len;
    new_entry->data = (char *)(new_entry + 1);

    if (copy_from_user(new_entry->data, user_buf, user_len)) {
        kfree(new_entry);
        mutex_unlock(&entry_lock);
        return -EFAULT;
    }

    entries[idx] = *new_entry;
    kfree(new_entry);  // line 44: 释放栈上副本，entries[idx] 悬垂

    mutex_unlock(&entry_lock);
    return 0;
}

static int __init vuln_init(void)
{
    entries = kcalloc(MAX_ENTRIES, sizeof(struct entry), GFP_KERNEL);
    if (!entries)
        return -ENOMEM;
    return 0;
}

static void __exit vuln_exit(void)
{
    int i;
    for (i = 0; i < MAX_ENTRIES; i++) {
        if (entries[i].data)
            kfree(entries[i].data);  // line 56: 悬垂指针使用
    }
    kfree(entries);
}

