#include <iostream>
#include <thread>
#include <mutex>
#include <vector>

class Buffer {
public:
    Buffer(size_t size) : data_(new char[size]), size_(size), mutex_() {}
    ~Buffer() {
        std::lock_guard<std::mutex> lock(mutex_);
        delete[] data_;
    }

    void resize(size_t new_size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (new_size == 0) {
            delete[] data_;
            data_ = nullptr;
            size_ = 0;
            return;
        }
        char* new_data = new char[new_size];
        std::copy(data_, data_ + std::min(size_, new_size), new_data);
        delete[] data_;
        data_ = new_data;
        size_ = new_size;
    }

    void write(char c) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_ == nullptr) {
            std::cout << "Buffer is null\n";
            return;
        }
        data_[0] = c;
    }

private:
    char* data_;
    size_t size_;
    std::mutex mutex_;
};

void thread_func(Buffer& buf) {
    for (int i = 0; i < 100; ++i) {
        buf.resize(128);
        buf.write('x');
    }
}

int main() {
    Buffer buf(64);
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back(thread_func, std::ref(buf));
    }
    for (auto& t : threads) {
        t.join();
    }
    return 0;
}

