struct ImageHeader {
    uint32_t width;
    uint32_t height;
    uint16_t bpp; // bits per pixel
    uint8_t  compression;
};

bool decodeImage(const uint8_t* rawData, size_t dataSize, ImageHeader& hdr, std::vector<uint8_t>& outPixels) {
    if (rawData == nullptr || dataSize < sizeof(ImageHeader)) {
        return false;
    }

    std::memcpy(&hdr, rawData, sizeof(ImageHeader));

    // Validate basic dimensions
    if (hdr.width == 0 || hdr.height == 0 || hdr.bpp == 0) {
        return false;
    }
    if (hdr.width > 8192 || hdr.height > 8192) {
        return false;
    }
    if (hdr.compression != 0 && hdr.compression != 1) {
        return false;
    }

    // Calculate bytes per row (with padding to 4-byte alignment)
    uint32_t rowBytes = (hdr.width * hdr.bpp + 7) / 8;
    uint32_t paddedRowBytes = (rowBytes + 3) & ~3U;

    // Vulnerable: integer overflow in multiplication
    uint32_t totalSize = paddedRowBytes * hdr.height;

    // Insufficient check: only against dataSize, not against SIZE_MAX
    if (totalSize > dataSize) {
        return false;
    }

    // Bypass check via overflow: if paddedRowBytes * height wraps, totalSize may be small
    outPixels.resize(totalSize);

    // Simulate decoding (copy raw pixel data)
    const uint8_t* pixelSrc = rawData + sizeof(ImageHeader);
    std::memcpy(outPixels.data(), pixelSrc, totalSize);

    std::cout << "Decoded " << hdr.width << "x" << hdr.height << " image, size=" << totalSize << std::endl;
    return true;
}

int main() {
    // Crafted malicious header: width=0x40000000, height=0x10, bpp=24
    // rowBytes = (0x40000000 * 24 + 7)/8 = 0xC0000000, paddedRowBytes = 0xC0000000
    // totalSize = 0xC0000000 * 0x10 = 0x0 (mod 2^32) -> passes check
    ImageHeader evilHdr = {0x40000000, 0x10, 24, 0};
    std::vector<uint8_t> fakeData(sizeof(ImageHeader) + 100, 0xFF);
    std::memcpy(fakeData.data(), &evilHdr, sizeof(evilHdr));

    std::vector<uint8_t> outPixels;
    bool ok = decodeImage(fakeData.data(), fakeData.size(), evilHdr, outPixels);
    std::cout << "Decode result: " << (ok ? "success" : "fail") << std::endl;
    return 0;
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

// Config 模拟从配置文件加载的监控目标列表
type Config struct {
	AllowedHosts []string `json:"allowed_hosts"` // 可信的 API 域名白名单
}

var globalConfig Config

func loadConfig(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, &globalConfig)
}

// fetchMetrics 从指定的 API 端点拉取指标，用于定时上报
func fetchMetrics(rawURL string) ([]byte, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid url: %w", err)
	}

	// 白名单校验：只允许访问配置中列出的主机
	host := parsed.Hostname()
	allowed := false
	for _, h := range globalConfig.AllowedHosts {
		if h == host {
			allowed = true
			break
		}
	}
	if !allowed {
		return nil, fmt.Errorf("host %q not in allowed list", host)
	}

	// 仅允许 http/https 协议，防止 file:// 等非预期协议
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return nil, fmt.Errorf("scheme %q not allowed", parsed.Scheme)
	}

	// 发起 HTTP 请求（此处模拟，真实场景会使用 http.Client）
	resp, err := http.Get(parsed.String())
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

// scheduledJob 定时任务入口：每 30 秒拉取一次指标
func scheduledJob() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		// 模拟从环境变量或配置中心动态获取目标地址（攻击者可控）
		target := os.Getenv("METRICS_API_URL")
		if target == "" {
			continue
		}
		data, err := fetchMetrics(target)
		if err != nil {
			fmt.Printf("fetch failed: %v\n", err)
			continue
		}
		fmt.Printf("metrics fetched: %d bytes\n", len(data))
	}
}

func main() {
	if err := loadConfig("/etc/metrics/config.json"); err != nil {
		panic(err)
	}
	go scheduledJob()
	select {}
}
